import React, { useState } from 'react';
import axios from 'axios';
import './Dashboard.css';
import Globe3D from './components/Globe3D';
import RiskRadarChart from './components/RiskRadarChart';

const Dashboard = () => {
    const [result, setResult] = useState(null);
    const [wellness, setWellness] = useState(null);
    const [loading, setLoading] = useState(false);

    const handleUpload = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        setLoading(true);
        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await axios.post('http://localhost:5000/predict', formData);
            setResult(res.data);

            const wellRes = await axios.post('http://localhost:5000/get_wellness_info', { condition: res.data.class });
            setWellness(wellRes.data.html_content);
        } catch (error) {
            console.error("Error during analysis:", error);
            alert("Analysis failed. Is the Flask backend running on port 5000?");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="dashboard-container">
            {/* BACKGROUND: Fixed Globe */}
            <div id="scene-globe">
                <Globe3D />
            </div>

            {/* FOREGROUND: Analysis Panel */}
            <section id="scene-analysis">
                <div style={{ width: '90%', maxWidth: '1200px', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '40px', color: 'white' }}>

                    {/* Left: Controls */}
                    <div>
                        <h1 style={{ fontSize: '3rem', fontWeight: 'bold' }}>OralScan AI</h1>
                        <input type="file" onChange={handleUpload} style={{ marginTop: '20px', padding: '10px' }} accept="image/*" />

                        {loading && <p>Analyzing...</p>}

                        {result && (
                            <div style={{ marginTop: '30px', padding: '20px', background: 'rgba(255,255,255,0.1)', borderRadius: '15px' }}>
                                <h2 style={{ color: '#60a5fa' }}>{result.class} ({result.confidence.toFixed(1)}%)</h2>
                                {wellness && <div dangerouslySetInnerHTML={{ __html: wellness }} />}
                            </div>
                        )}
                    </div>

                    {/* Right: Risk Radar */}
                    <div style={{ background: '#1e293b', padding: '30px', borderRadius: '20px' }}>
                        <h3>Patient Risk Profile</h3>
                        <RiskRadarChart />
                    </div>

                </div>

                <div style={{ position: 'absolute', bottom: '20px', color: 'white', animation: 'bounce 2s infinite', textAlign: 'center', width: '100%' }}>
                    ↓ Scroll to Reveal Global Data ↓
                </div>
            </section>

            {/* SPACER: Triggers the Reveal */}
            <section id="scroll-spacer"></section>
        </div>
    );
};
export default Dashboard;
